@KafkaListener(topics = "${migration.dualwrite.topic}",
               groupId = "petstore-migration-group")
public void onOrderEvent(OrderDualWriteEvent event) {
  switch (event.getEventType()) {
    case ORDER_CREATED        -> mongoTemplate.save(event.getOrder(), ORDERS);
    case ORDER_STATUS_UPDATED -> applyStatus(event);   // updateFirst by _id
    case ORDER_CANCELLED      -> cancel(event);
  }
  metrics.recordDualWriteSuccess();     // rethrows on failure -> DLQ
}

